def solve(n):
    g=np.array(G[f'Demo pair {n} input']); o=np.array(G[f'Demo pair {n} output'])
    cnt=Counter(g.flatten()); bg=cnt.most_common(1)[0][0]
    hl=[r for r in range(g.shape[0]) if len(set(map(int,g[r])))>=2 and sum(x==bg for x in g[r])/g.shape[1]<=0.6]
    vl=[c for c in range(g.shape[1]) if len({int(g[r,c]) for r in range(g.shape[0])})>=2 and sum(g[:,c]==bg)/g.shape[0]<=0.6]
    out=[]
    for i in range(len(hl)-1):
        row=[]
        for j in range(len(vl)-1):
            corners=[int(g[hl[i+k],vl[j+l]]) for k in (0,1) for l in (0,1)]
            s=set(corners)
            if len(s)==1:
                v=s.pop()
                row.append(v if v not in (bg,linecolor(g,bg)) else bg)
            else:
                row.append(bg)
        out.append(row)
    return np.array(out),o.tolist()
for n in ['1','2','3']:
